1	`timescale 1ns / 1ps
2	// Self-checking WB-stage monitor for lab2 RV32core running rom.mem.
3	// Golden trace hand-derived from lab2/exp_test.s + ram.mem.
4	// Run vvp from a directory containing rom.mem/ram.mem (lab2/core).
5	module tb_lab2_check;
6	    reg clk, rst;
7	    integer cycle = 0;
8	    integer idx = 0;      // index into golden table
9	    integer errors = 0;
10	
11	    RV32core core(
12	        .debug_en(1'b0),
13	        .debug_step(1'b0),
14	        .debug_addr(7'b0),
15	        .debug_data(),
16	        .clk(clk),
17	        .rst(rst),
18	        .wb_pc(),
19	        .wb_inst(),
20	        .mem_addr(),
21	        .mem_data(),
22	        .interrupter(1'b0)
23	    );
24	
25	    // golden table: {pc[31:0], rd[4:0], data[31:0]}
26	    localparam N = 44;
27	    reg [68:0] golden [0:N-1];
28	    initial begin
29	        // main: loads
30	        golden[ 0] = {32'h04, 5'd2,  32'h00000008}; // lw x2,4(x0)
31	        golden[ 1] = {32'h08, 5'd4,  32'h00000010}; // lw x4,8(x0)
32	        golden[ 2] = {32'h0c, 5'd5,  32'h00000014}; // lw x5,12(x0)
33	        golden[ 3] = {32'h10, 5'd6,  32'hffff0000}; // lw x6,16(x0)
34	        golden[ 4] = {32'h14, 5'd7,  32'h0fff0000}; // lw x7,20(x0)
35	        // main: CSR ops on 0x306
36	        golden[ 5] = {32'h18, 5'd1,  32'h00000000}; // csrrwi x1,0x306,16 (old=0)
37	        golden[ 6] = {32'h1c, 5'd1,  32'h00000010}; // csrr x1,0x306
38	        golden[ 7] = {32'h20, 5'd1,  32'h00000010}; // csrrw x1,0x306,x6 (old=0x10)
39	        golden[ 8] = {32'h24, 5'd1,  32'hffff0000}; // csrr x1,0x306
40	        golden[ 9] = {32'h2c, 5'd1,  32'h00000078}; // addi x1,x0,120
41	        // trap 1: ecall @0x38 -> handler
42	        golden[10] = {32'h78, 5'd25, 32'h00000038}; // csrr x25,mepc
43	        golden[11] = {32'h7c, 5'd27, 32'h0000000b}; // csrr x27,mcause
44	        golden[12] = {32'h80, 5'd28, 32'h00001880}; // csrr x28,mstatus
45	        golden[13] = {32'h84, 5'd29, 32'h00000000}; // csrr x29,mtval
46	        golden[14] = {32'h88, 5'd30, 32'h00000000}; // csrr x30,mip
47	        golden[15] = {32'h8c, 5'd2,  32'h0000003c}; // addi x2,x25,4
48	        // trap 2: illegal @0x40 -> handler
49	        golden[16] = {32'h78, 5'd25, 32'h00000040};
50	        golden[17] = {32'h7c, 5'd27, 32'h00000002};
51	        golden[18] = {32'h80, 5'd28, 32'h00001880};
52	        golden[19] = {32'h84, 5'd29, 32'h00000012}; // mtval = faulting inst
53	        golden[20] = {32'h88, 5'd30, 32'h00000000};
54	        golden[21] = {32'h8c, 5'd2,  32'h00000044};
55	        // lw x1,127(x0) @0x48 (in range, byte=0)
56	        golden[22] = {32'h48, 5'd1,  32'h00000000};
57	        // trap 3: load access fault @0x4c -> handler
58	        golden[23] = {32'h78, 5'd25, 32'h0000004c};
59	        golden[24] = {32'h7c, 5'd27, 32'h00000005};
60	        golden[25] = {32'h80, 5'd28, 32'h00001880};
61	        golden[26] = {32'h84, 5'd29, 32'h00000080}; // mtval = faulting addr
62	        golden[27] = {32'h88, 5'd30, 32'h00000000};
63	        golden[28] = {32'h8c, 5'd2,  32'h00000050};
64	        // trap 4: store access fault @0x54 -> handler
65	        golden[29] = {32'h78, 5'd25, 32'h00000054};
66	        golden[30] = {32'h7c, 5'd27, 32'h00000007};
67	        golden[31] = {32'h80, 5'd28, 32'h00001880};
68	        golden[32] = {32'h84, 5'd29, 32'h00000080}; // mtval = faulting addr
69	        golden[33] = {32'h88, 5'd30, 32'h00000000};
70	        golden[34] = {32'h8c, 5'd2,  32'h00000058};
71	        // jr x0 @0x74 -> second pass starts (CSR[6] now 0xffff0000)
72	        golden[35] = {32'h04, 5'd2,  32'h00000008};
73	        golden[36] = {32'h08, 5'd4,  32'h00000010};
74	        golden[37] = {32'h0c, 5'd5,  32'h00000014};
75	        golden[38] = {32'h10, 5'd6,  32'hffff0000};
76	        golden[39] = {32'h14, 5'd7,  32'h0fff0000};
77	        golden[40] = {32'h18, 5'd1,  32'hffff0000}; // csrrwi old=0xffff0000
78	        golden[41] = {32'h1c, 5'd1,  32'h00000010};
79	        golden[42] = {32'h20, 5'd1,  32'h00000010};
80	        golden[43] = {32'h24, 5'd1,  32'hffff0000};
81	    end
82	
83	    initial begin
84	        clk = 0;
85	        rst = 1;
86	        #2 rst = 0;
87	    end
88	    always #1 clk = ~clk;
89	
90	    always @(posedge clk) begin
91	        cycle = cycle + 1;
92	        if (!rst) begin
93	            if (core.RegWrite_WB && !core.RegWrite_cancel_exp) begin
94	                if (^core.wt_data_WB === 1'bx || ^core.rd_WB === 1'bx || ^core.PC_WB === 1'bx) begin
95	                    $display("FAIL X-prop cycle=%0d pc=%h rd=%h data=%h",
96	                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
97	                    errors = errors + 1;
98	                end else if (core.rd_WB != 5'd0) begin
99	                    if (idx < N) begin
100	                        if ({core.PC_WB, core.rd_WB, core.wt_data_WB} !== golden[idx]) begin
101	                            $display("FAIL idx=%0d cycle=%0d got pc=%h rd=x%0d data=%h, expected pc=%h rd=x%0d data=%h",
102	                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB,
103	                                     golden[idx][68:37], golden[idx][36:32], golden[idx][31:0]);
104	                            errors = errors + 1;
105	                        end else begin
106	                            $display("PASS idx=%0d cycle=%0d pc=%h rd=x%0d data=%h",
107	                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
108	                        end
109	                        idx = idx + 1;
110	                    end
111	                end
112	            end
113	        end
114	        if (cycle > 200) begin
115	            if (idx < N) begin
116	                $display("FAIL only %0d of %0d expected WB writes observed", idx, N);
117	                errors = errors + 1;
118	            end
119	            $display("RESULT errors=%0d checked=%0d", errors, idx);
120	            $finish;
121	        end
122	    end
123	endmodule
